mapper.select:
SELECT COUNT(*) as id, AVG(wait_duration) as wait_duration, AVG(handle_duration) as handle_duration, AVG(total_duration) as total_duration, SUM(CASE WHEN status = 'COMPLETED' THEN 1 ELSE 0 END) as assignee_id, SUM(CASE WHEN status = 'TIMEOUT' THEN 1 ELSE 0 END) as tenant_id FROM wf_task_monitor WHERE tenant_id = #{tenantId}
AND create_time_task >= #{startTime}
AND create_time_task <= #{endTime}
